$('duplicate').onclick=()=>{const list=selectedObjects();if(!list.length)return;if(list.length+state.objects.length>40)return toast('A scene supports up to 40 sculptures.');checkpoint();const groups=new Map(),copies=list.map(o=>{if(o.assembly&&!groups.has(o.assembly))groups.set(o.assembly,uid());return {...clone(o),id:uid(),name:o.name+' copy',assembly:o.assembly?groups.get(o.assembly):null,x:Math.min(12,o.x+1.5)};});state.objects.push(...copies);selected=new Set(copies.map(o=>o.id));activeId=copies[0].id;copies.forEach(addRender);renderUI();persist();};
$('delete').onclick=()=>{if(!selected.size)return;endObjectDrag();checkpoint();selected.forEach(id=>{if(objects.has(id)){disposeRender(objects.get(id));objects.delete(id);}});state.objects=state.objects.filter(o=>!selected.has(o.id));selected.clear();activeId=null;setMode('orbit');renderUI();persist();};$('group').onclick=()=>{if(selected.size<2)return;checkpoint();const id=uid();selectedObjects().forEach(o=>o.assembly=id);renderUI();persist();toast('Assembly linked');};$('unlink').onclick=()=>{checkpoint();selectedObjects().forEach(o=>o.assembly=null);renderUI();persist();toast('Pieces separated');};
$('center').onclick=()=>{const list=selectedObjects();if(!list.length)return;checkpoint();const x=list.reduce((v,o)=>v+o.x,0)/list.length,z=list.reduce((v,o)=>v+o.z,0)/list.length;list.forEach(o=>{o.x=clamp(o.x-x,-12,12);o.z=clamp(o.z-z,-12,12);});renderUI();persist();toast('Selection centered');};
$('object-name').onfocus=()=>checkpoint();$('object-name').oninput=()=>{const o=active();if(o){o.name=$('object-name').value.trim()||types[o.type];persist();}};$('object-name').onblur=()=>renderUI();$('scene-name').onfocus=()=>checkpoint();$('scene-name').oninput=()=>{state.name=$('scene-name').value.trim()||'Untitled study';persist();};
function bindInput(id,callback){let begun=false;$(id).oninput=()=>{if(!begun){checkpoint();begun=true;}callback($(id).value);};$(id).onchange=()=>{begun=false;persist();renderManipulate();};}
bindInput('tint',v=>selectedObjects().forEach(o=>{o.tint=v;const m=objects.get(o.id).mat;m.color.set(v);if(o.material==='neon')m.emissive.set(v);}));for(const id of ['accent','light','fog','tempo'])bindInput(id,v=>{state[id]=id==='accent'?v:Number(v);environment();$('tempo-val').textContent=state.tempo.toFixed(2)+'×';});for(const id of ['grid','autorotate'])$(id).onchange=()=>{checkpoint();state[id]=$(id).checked;environment();persist();};
function dialog(title,html){$('modal-title').textContent=title;$('modal-body').innerHTML=html;$('modal').showModal();}$('close-modal').onclick=()=>{if(exportingSaver)cancelSaver=true;$('modal').close();};$('modal').addEventListener('cancel',()=>{if(exportingSaver)cancelSaver=true;});
function confirmReplace(fn){if(!state.objects.length)return fn();dialog('Start a new composition?','<p>Your current work will stay available through Undo. Save it to My scenes if you want to keep it in your library.</p><div class="modal-actions"><button id="cancel-replace">Keep working</button><button id="confirm-replace" class="primary">Start new</button></div>');$('cancel-replace').onclick=()=>$('modal').close();$('confirm-replace').onclick=()=>{$('modal').close();fn();};}
function loadStudy(which){checkpoint();state=defaults();if(which==='orbit'){state.name='Study 002 — Celestial';state.objects=[make('rings',{count:6,size:2.4,amplitude:1,speed:.3}),make('sphere',{name:'Amber core',size:1.1,material:'gold',tint:finishes.gold.color}),make('helix',{name:'Satellite spiral',count:1,size:1.2,x:-4,y:2.2,speed:.5,material:'gold',tint:finishes.gold.color})];}if(which==='bloom'){state.name='Study 003 — Mechanical bloom';state.objects=[make('bloom',{count:16,y:1,size:2.5,spacing:.4,amplitude:.8,speed:.5,material:'gold',tint:finishes.gold.color}),make('sphere',{name:'Heart',y:1.2,size:1,material:'neon',tint:finishes.neon.color}),make('torus',{name:'Foundation',y:.25,size:1.3,rx:Math.PI/2,thickness:.1,motion:'still'})];state.accent='#e6b56a';}if(which==='wave'){state.name='Study 004 — Resonance';state.objects=[make('pendulums',{count:24,size:2.3,y:3.4,spacing:.02,amplitude:.8,speed:.8,twist:.25,motion:'wave'}),make('ribbon',{name:'Wave ribbon',count:1,y:1.2,size:2,material:'gold',tint:finishes.gold.color,speed:.2})];}selected=new Set([state.objects[0].id]);activeId=[...selected][0];time=0;rebuild();persist();$('home').click();toast('Starting point loaded · every piece is editable');}
document.querySelectorAll('[data-study]').forEach(b=>b.onclick=()=>confirmReplace(()=>loadStudy(b.dataset.study)));$('blank').onclick=()=>confirmReplace(()=>{checkpoint();state.objects=[];state.name='Untitled study';selected.clear();activeId=null;rebuild();persist();});$('first-form').onclick=()=>add('frames');
function validate(raw){if(!raw||raw.version!==1||!Array.isArray(raw.objects)||raw.objects.length>40)throw Error('Unsupported scene file.');const s=defaults(),bounds={count:[1,32],size:[.2,4],spacing:[0,1],twist:[-1,1],thickness:[.02,.3],speed:[-2,2],phase:[0,6.28],amplitude:[0,2],x:[-12,12],y:[0,12],z:[-12,12],scale:[.1,3],rx:[-3.14,3.14],ry:[-3.14,3.14],rz:[-3.14,3.14]},num=(v,f,a,b)=>Number.isFinite(v)?clamp(v,a,b):f,color=v=>typeof v==='string'&&/^#[0-9a-f]{6}$/i.test(v);s.name=typeof raw.name==='string'?raw.name.slice(0,60):'Imported study';s.objects=raw.objects.map(r=>{if(!r||!Object.hasOwn(types,r.type))throw Error('Scene contains an unknown form.');const o=make(r.type);o.name=typeof r.name==='string'?r.name.slice(0,50):types[r.type];for(const [k,[min,max]]of Object.entries(bounds)){if(typeof r[k]!=='number'||!Number.isFinite(r[k]))throw Error('Scene contains an invalid parameter.');o[k]=clamp(r[k],min,max);}o.count=Math.round(o.count);o.material=Object.hasOwn(finishes,r.material)?r.material:'silver';o.tint=color(r.tint)?r.tint:finishes[o.material].color;o.motion=['flow','spin','breathe','wave','still'].includes(r.motion)?r.motion:'flow';o.axis=['x','y','z'].includes(r.axis)?r.axis:'y';o.assembly=typeof r.assembly==='string'?r.assembly.slice(0,80):null;o.stretch=[0,1,2].map(i=>num(r.stretch?.[i],1,.05,4));o.sculpt=sanitizeSculpt(r.sculpt,o.count);return o;});for(const [k,a,b]of [['light',.3,2],['fog',0,.06],['tempo',0,2]])s[k]=num(raw[k],s[k],a,b);s.accent=color(raw.accent)?raw.accent:s.accent;s.grid=raw.grid===true;s.autorotate=raw.autorotate===true;return s;}
function library(){try{const x=JSON.parse(localStorage.getItem('xemory-playground-scenes-v1')||'[]');return Array.isArray(x)?x:[];}catch{return [];}}
$('save').onclick=()=>{try{const list=library(),old=list.findIndex(x=>x.scene.name===state.name),item={id:uid(),date:new Date().toISOString(),scene:clone(state)};if(old>=0)list[old]=item;else if(list.length>=50)return toast('Your library is full. Export or remove a scene first.');else list.unshift(item);localStorage.setItem('xemory-playground-scenes-v1',JSON.stringify(list));toast('Scene saved on this browser');}catch{toast('Could not save. Export your scene to keep it.');}};
$('library').onclick=()=>{dialog('My scenes','<p>Scenes are saved on this browser. Export a scene to back it up or move it to another device.</p><div id="saved-list"></div>');const list=library();let draft=null;try{draft=JSON.parse(localStorage.getItem('xemory-playground-draft-v1')||'null');}catch{}const entries=[...(draft?[{id:'draft',date:null,scene:draft}]:[]),...list];if(!entries.length){$('saved-list').textContent='No saved scenes yet. Choose Save scene to keep a composition.';return;}for(const item of entries){const row=document.createElement('div');row.className='saved-item';const text=document.createElement('div');text.textContent=item.id==='draft'?'Last draft · '+item.scene.name:item.scene.name;const sub=document.createElement('small');sub.textContent=item.id==='draft'?'Autosaved in this browser':new Date(item.date).toLocaleDateString();text.append(sub);const open=document.createElement('button');open.textContent='Open';open.onclick=()=>{try{const next=validate(item.scene);checkpoint();state=next;selected=new Set(state.objects[0]?[state.objects[0].id]:[]);activeId=[...selected][0]||null;time=0;rebuild();persist();$('modal').close();}catch{toast('This scene could not be read');}};row.append(text,open);if(item.id!=='draft'){const remove=document.createElement('button');remove.textContent='Delete';remove.onclick=()=>{try{localStorage.setItem('xemory-playground-scenes-v1',JSON.stringify(library().filter(x=>x.id!==item.id)));row.remove();}catch{toast('Could not update the library');}};row.append(remove);}$('saved-list').append(row);}};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}const filename=()=>state.name.replace(/[^a-z0-9_-]+/gi,'-').slice(0,60)||'kinetic-scene';$('export').onclick=()=>download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),filename()+'.kinetic.json');$('capture').onclick=()=>{const shown=selectionBox.visible;selectionBox.visible=false;brushRing.visible=false;renderer.render(scene,camera);$('canvas').toBlob(blob=>{if(blob)download(blob,filename()+'.png');else toast('Image capture failed');},'image/png');selectionBox.visible=shown;};$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{const f=$('file').files[0];$('file').value='';if(!f)return;if(f.size>1000000)return toast('Scene file is too large (maximum 1 MB).');try{const next=validate(JSON.parse(await f.text()));checkpoint();state=next;selected=new Set(state.objects[0]?[state.objects[0].id]:[]);activeId=[...selected][0]||null;time=0;rebuild();persist();toast('Scene imported');}catch(e){toast(e.message||'This scene could not be imported');}};

$('screensaver').onclick=()=>{
 if(exportingSaver)return;endObjectDrag();
 dialog('Download your moving artwork',`<p>Capture a five-second loop of your composition in the current camera view. Both downloads are free and created on this device.</p><div class="saver-options"><button id="saver-browser"><b>Browser artwork loop</b><span>Offline HTML · open in your browser and enjoy fullscreen</span><i>↓</i></button><button id="saver-video"><b>Video loop</b><span>WebM video · save and share</span><i>↓</i></button></div><p class="saver-note">The browser loop is a viewer; it does not start automatically when your computer is idle. ${state.tempo===0?'Tempo is zero, so the loop will be still. Increase Tempo for motion.':'Capture follows Tempo even when the editor is frozen.'}</p><div id="saver-progress" role="status" aria-live="polite"></div>`);
 const run=async kind=>{if(exportingSaver)return;cancelSaver=false;exportingSaver=true;const browser=$('saver-browser'),video=$('saver-video'),progress=$('saver-progress');browser.disabled=video.disabled=true;
 try{const frames=await captureFrames({renderer,camera,scene,objects,state,startTime:time,selectionBox,brushRing,stage:$('stage'),onProgress:(i,n)=>{progress.textContent=`Rendering your artwork · ${i} / ${n} frames`;},isCancelled:()=>cancelSaver});if(cancelSaver)return;progress.textContent='Preparing your download…';const blob=kind==='video'?await makeVideoLoop(frames,()=>cancelSaver):await makeBrowserLoop(frames);if(cancelSaver)return;download(blob,filename()+(kind==='video'?'-artwork-loop.webm':'-artwork-loop.html'));progress.textContent='Your download is ready.';}catch(e){if(!e.cancelled)progress.textContent=e.message||'Could not create the download. Please try again.';}finally{exportingSaver=false;if(browser.isConnected)browser.disabled=false;if(video.isConnected)video.disabled=false;}};
 $('saver-browser').onclick=()=>run('browser');$('saver-video').onclick=()=>run('video');
};
$('guide').onclick=()=>dialog('Make something move you','<p>Start with a form, give it a rhythm, and keep making it yours.</p><h3>1 · Add and combine</h3><p>Choose a form from the left library. Select it in the canvas or the Scene list. Shift-click to select several pieces, then use Assemble to move them together. Duplicate and Delete are above the Scene list.</p><h3>2 · Shape and move</h3><p>Use the inspector to change repetitions, size, spacing, twist, material, color, and movement. Choose Move and drag the selected form to position it, or use the exact position controls. Drag empty space to orbit the camera; scroll to zoom.</p><h3>3 · Sculpt the surface</h3><p>Select a sculpture, press Manipulate, then choose Pull, Twist, or Inflate. Drag the visible surface. Twist uses left/right motion; Inflate uses up/down motion. Brush reach changes the affected area. Strokes stay after release; Undo reverses them and Clear shape removes them. Freeze lets you work while motion is paused.</p><h3>4 · Keep your work</h3><p>Save scene and My scenes use this browser’s local storage. Export creates a portable scene file; Import opens one. Capture saves an image. Download artwork creates a free browser loop or WebM video from your current view. The latest draft is available in My scenes.</p><p><b>Shortcuts:</b> G Manipulate, M Move, O Orbit, Space pause, Ctrl/Cmd Z Undo, Ctrl/Cmd Shift Z Redo, Ctrl/Cmd D Duplicate, Delete remove.</p><p>There are up to 40 sculptures per scene, 32 repetitions per sculpture, and 64 sculpt strokes per sculpture.</p>');
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)||$('modal').open)return;const ctrl=e.ctrlKey||e.metaKey;if(ctrl&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);}else if(ctrl&&e.key.toLowerCase()==='d'){e.preventDefault();$('duplicate').click();}else if(ctrl&&e.key.toLowerCase()==='s'){e.preventDefault();$('save').click();}else if(e.code==='Space'){e.preventDefault();togglePause();}else if(e.key==='Delete'||e.key==='Backspace')$('delete').click();else if(e.key==='Escape')setMode('orbit');else if(e.key.toLowerCase()==='g'&&active())$('manipulate').click();else if(e.key.toLowerCase()==='m')setMode('move');else if(e.key.toLowerCase()==='o')setMode('orbit');});
new ResizeObserver(()=>{const r=$('stage').getBoundingClientRect();if(!r.width||!r.height)return;renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}).observe($('stage'));
let last=performance.now(),frames=0,lastFPS=last;function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-last)/1000,.06);last=now;if(exportingSaver)return;if(!paused)time+=dt*state.tempo;for(const o of state.objects)if(!(drag?.kind==='sculpt'&&drag.id===o.id))updateShape(o,objects.get(o.id),time);if(!drag)controls.update();selectionBox.visible=!!active();selectionBox.material.color.set(mode==='manipulate'?0xf3c78d:0x7de3ed);if(selectionBox.visible){selectionBox.box.makeEmpty();selectedObjects().forEach(x=>selectionBox.box.expandByObject(objects.get(x.id).root));}renderer.render(scene,camera);$('clock').textContent=`${String(Math.floor(time/60)).padStart(2,'0')}:${String(Math.floor(time%60)).padStart(2,'0')}`;frames++;if(now-lastFPS>1000){$('fps').textContent=`${Math.round(frames*1000/(now-lastFPS))} FPS`;frames=0;lastFPS=now;}}
rebuild();requestAnimationFrame(animate);

